import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    df = inputs["app_events"].copy()

    # Ensure proper dtypes
    df["event_ts"] = pd.to_datetime(df["event_ts"])
    if "user_id" in df.columns:
        df["user_id"] = df["user_id"]
    if "event_id" in df.columns:
        df["event_id"] = df["event_id"]

    out_cols = [
        "user_id",
        "session_num",
        "session_start",
        "session_end",
        "event_count",
        "heartbeat_count",
    ]

    if df.empty:
        return {"user_sessions": pd.DataFrame(columns=out_cols)}

    threshold = timedelta(minutes=30)

    records = []

    # Stable sort by event_ts then event_id, within each user
    df_sorted = df.sort_values(by=["user_id", "event_ts", "event_id"], kind="mergesort")

    for user_id, group in df_sorted.groupby("user_id", sort=False):
        session_counter = 0
        open_session = None  # dict with session_num, session_start, last_activity, event_count, heartbeat_count

        for _, row in group.iterrows():
            ts = row["event_ts"]
            etype = row["event_type"]

            if etype in ("view", "click", "logout"):
                # Determine if a new session must start
                if open_session is None or (ts - open_session["last_activity"]) > threshold:
                    if open_session is not None:
                        # finalize any lingering open session (shouldn't normally happen
                        # since sessions close only via logout or starting a new one,
                        # but guard just in case)
                        records.append(
                            {
                                "user_id": user_id,
                                "session_num": open_session["session_num"],
                                "session_start": open_session["session_start"],
                                "session_end": open_session["last_activity"],
                                "event_count": open_session["event_count"],
                                "heartbeat_count": open_session["heartbeat_count"],
                            }
                        )
                    session_counter += 1
                    open_session = {
                        "session_num": session_counter,
                        "session_start": ts,
                        "last_activity": ts,
                        "event_count": 0,
                        "heartbeat_count": 0,
                    }
                else:
                    open_session["last_activity"] = ts

                open_session["event_count"] += 1

                if etype == "logout":
                    records.append(
                        {
                            "user_id": user_id,
                            "session_num": open_session["session_num"],
                            "session_start": open_session["session_start"],
                            "session_end": open_session["last_activity"],
                            "event_count": open_session["event_count"],
                            "heartbeat_count": open_session["heartbeat_count"],
                        }
                    )
                    open_session = None

            else:  # heartbeat
                if open_session is not None and (ts - open_session["last_activity"]) <= threshold:
                    open_session["event_count"] += 1
                    open_session["heartbeat_count"] += 1
                # else: dropped, no effect

        if open_session is not None:
            records.append(
                {
                    "user_id": user_id,
                    "session_num": open_session["session_num"],
                    "session_start": open_session["session_start"],
                    "session_end": open_session["last_activity"],
                    "event_count": open_session["event_count"],
                    "heartbeat_count": open_session["heartbeat_count"],
                }
            )

    result_df = pd.DataFrame.from_records(records, columns=out_cols)

    return {"user_sessions": result_df}
